import { loadFont } from "@remotion/fonts";
import { firaCodeBoldUrl, firaCodeRegularUrl } from "./fonts-data";

// Fonts inlined as base64 data URIs (src/fonts-data.ts, generated by
// scripts/inline-fonts.cjs) instead of fetching from the bundle server:
// under render load the font fetch could stall, holding a delayRender
// handle until it timed out and killed the render.
export const fontFamily = "Fira Code";

// FontFace only exists in the browser; under Node (vitest) there is no
// DOM to load fonts into, so resolve immediately.
const fontReady =
  typeof FontFace === "undefined"
    ? Promise.resolve()
    : Promise.all([
        loadFont({
          family: fontFamily,
          url: firaCodeRegularUrl,
          weight: "400",
          format: "truetype",
        }),
        loadFont({
          family: fontFamily,
          url: firaCodeBoldUrl,
          weight: "700",
          format: "truetype",
        }),
      ]).then(() => undefined);

export const waitUntilDone = () => fontReady;

export const fontSize = 40;
export const tabSize = 3;
export const horizontalPadding = 60;
export const verticalPadding = 84;
